pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, address caddress, address a, address b, uint256 v) public {
        // The callee must accept calls; use this test contract as a recorder that always commits.
        caddress = address(this);
        address[] memory tos = new address[](2);
        tos[0] = a;
        tos[1] = b;
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok, "two-recipient transfer should succeed when callee accepts");
    }

    // Fallback accepts all calls from C so that the external call success condition is met.
    fallback() external payable {}
}
